<style>
@font-face{font-family:"EC915 Sans";src:url("/theme-demo/ec915/fonts/BeVietnamPro-Regular.ttf") format("truetype");font-weight:400;font-display:swap}
@font-face{font-family:"EC915 Sans";src:url("/theme-demo/ec915/fonts/BeVietnamPro-SemiBold.ttf") format("truetype");font-weight:600;font-display:swap}
@font-face{font-family:"EC915 Sans";src:url("/theme-demo/ec915/fonts/BeVietnamPro-Bold.ttf") format("truetype");font-weight:700;font-display:swap}
:root{--ec15-copper:#b97c58;--ec15-copper-dark:#8b5536;--ec15-ink:#171717;--ec15-muted:#7f8799;--ec15-paper:#f4ebe6;--ec15-line:#e8ddd7;--ec15-shadow:0 18px 45px rgba(40,25,18,.1)}
*{box-sizing:border-box}.ec15-page{font-family:"EC915 Sans",Arial,sans-serif;color:var(--ec15-ink);background:#fff}.ec15-page a{color:inherit;text-decoration:none}.ec15-page img{display:block;max-width:100%}.ec15-container{width:min(1540px,calc(100% - 44px));margin:auto}.ec15-header{position:absolute;z-index:50;left:0;right:0;top:0;color:#fff;background:rgba(20,17,15,.48);border-bottom:1px solid rgba(255,255,255,.1);transition:.35s}.ec15-header.is-scrolled{position:fixed;background:rgba(20,18,17,.94);box-shadow:0 8px 26px rgba(0,0,0,.16);backdrop-filter:blur(14px)}.ec15-header-inner{height:92px;display:flex;align-items:center;gap:42px}.ec15-logo{display:flex;align-items:center;gap:9px;min-width:270px;color:#fff}.ec15-logo img{max-height:62px;max-width:240px}.ec15-logo span{font-size:40px;line-height:1;font-weight:600;letter-spacing:-4px}.ec15-logo b{font-size:26px}.ec15-header nav{display:flex;align-items:center;justify-content:center;gap:30px;flex:1}.ec15-header nav a{font-size:14px;font-weight:600}.ec15-header nav a.active,.ec15-header nav a:hover{color:#d79a75}.ec15-header-actions{display:flex;align-items:center;gap:20px}.ec15-header-actions a,.ec15-header-actions button{border:0;background:transparent;color:#fff;font-size:21px;padding:0;position:relative}.ec15-cart em{position:absolute;right:-11px;top:-12px;width:18px;height:18px;border-radius:50%;background:var(--ec15-copper);font:10px "EC915 Sans";display:grid;place-items:center}.ec15-menu-toggle{display:none!important}.ec15-hero{height:100vh;min-height:700px}.ec15-hero-slider,.ec15-hero-slider article{position:relative;width:100%;height:100%;overflow:hidden}.ec15-hero-slider article{position:absolute;inset:0;opacity:0;transition:opacity .7s}.ec15-hero-slider article.is-active{opacity:1}.ec15-hero-slider article>img{width:100%;height:100%;object-fit:cover;transform:scale(1.04);transition:transform 7s ease}.ec15-hero-slider article.is-active>img{transform:scale(1)}.ec15-hero-shade{position:absolute;inset:0;background:rgba(18,15,13,.55)}.ec15-hero-copy{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#fff;padding:120px 12vw 40px}.ec15-hero-copy>span,.ec15-heading>span,.ec15-eyebrow{font-size:14px;letter-spacing:4px;font-weight:700;color:#d49a76;border-bottom:2px solid currentColor;padding-bottom:6px}.ec15-hero-copy h1{font-size:clamp(42px,5.2vw,80px);line-height:1.2;max-width:1480px;margin:34px 0 28px}.ec15-hero-copy p{font-size:17px;line-height:1.7;max-width:1200px}.ec15-hero-copy a{margin-top:24px;border:1px solid rgba(255,255,255,.7);padding:13px 22px;border-radius:3px}.ec15-hero-arrow{position:absolute;top:50%;width:42px;height:42px;border:0;border-radius:8px;background:#fff;color:var(--ec15-copper);z-index:3}.ec15-hero-arrow.prev{left:18px}.ec15-hero-arrow.next{right:18px}.ec15-section{padding:96px 0}.ec15-about-layout{display:grid;grid-template-columns:1fr .78fr;gap:100px;align-items:center}.ec15-about h2,.ec15-reasons h2,.ec15-faq h2{font-size:clamp(38px,4vw,62px);line-height:1.2;margin:24px 0}.ec15-about p,.ec15-reasons>div>div>p,.ec15-faq-layout>div>p{font-size:17px;line-height:1.75;color:var(--ec15-muted)}.ec15-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:34px}.ec15-stats article{background:var(--ec15-paper);border-radius:10px;border-bottom:4px solid var(--ec15-copper);text-align:center;padding:24px 12px}.ec15-stats b{display:block;font-size:34px;color:var(--ec15-copper)}.ec15-about figure{position:relative;margin:0}.ec15-about figure img{height:590px;width:100%;object-fit:cover;border-radius:16px}.ec15-about figure i{position:absolute;bottom:-34px;left:-34px;width:82px;height:82px;border-radius:50%;display:grid;place-items:center;background:#fff1d3;border:2px solid #d5ab75;font-size:28px;color:var(--ec15-copper-dark)}.ec15-categories{padding-top:45px}.ec15-room-grid{display:grid;grid-template-columns:1fr 1.3fr 1.3fr;grid-template-rows:250px 250px;gap:24px}.ec15-room-grid a{position:relative;border-radius:18px;overflow:hidden;background:#f4eee9;box-shadow:var(--ec15-shadow)}.ec15-room-grid .item-1{grid-row:span 2}.ec15-room-grid img{width:100%;height:100%;object-fit:cover}.ec15-room-grid a::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(246,237,229,.92),rgba(246,237,229,.08) 75%)}.ec15-room-grid span{position:absolute;z-index:2;left:28px;top:34px;width:45%}.ec15-room-grid b{display:block;font-size:25px;text-transform:uppercase;color:#673817}.ec15-room-grid small{display:block;color:#755d4b;line-height:1.5;margin:12px 0}.ec15-room-grid em{font-style:normal;color:#ff6500;font-weight:700}.ec15-heading{text-align:center;margin-bottom:48px}.ec15-heading h2{font-size:46px;margin:20px 0}.ec15-product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:28px}.ec15-product{background:var(--ec15-paper);border-radius:12px;padding:15px}.ec15-product-image{display:block;aspect-ratio:1;background:#fff;border-radius:10px;overflow:hidden;position:relative}.ec15-product-image img{width:100%;height:100%;object-fit:cover;transition:.4s}.ec15-product:hover img{transform:scale(1.05)}.ec15-product-image>span{position:absolute;left:12px;top:12px;color:#fff;background:var(--ec15-copper);border-radius:8px;padding:5px 12px;font-size:12px}.ec15-product-image>div{position:absolute;right:10px;top:10px;display:grid;gap:8px}.ec15-product-image>div i{background:#fff;border-radius:8px;padding:10px;box-shadow:0 3px 10px rgba(0,0,0,.08)}.ec15-product-meta{padding:18px 2px 5px}.ec15-product-meta h3{font-size:15px;line-height:1.5;min-height:46px}.ec15-product-meta p{display:flex;align-items:center;gap:12px}.ec15-product-meta del{color:#aaa}.ec15-product-meta strong{color:red;font-size:17px}.ec15-contact-banner{height:600px;position:relative}.ec15-contact-banner>img{width:100%;height:100%;object-fit:cover}.ec15-contact-banner .ec15-container{position:absolute;inset:0;display:flex;align-items:flex-end;justify-content:center;padding-bottom:20px}.ec15-contact-banner article{width:min(1200px,90%);background:rgba(181,116,79,.93);color:#fff;padding:42px 48px;display:grid;grid-template-columns:1fr auto auto;gap:38px;align-items:center}.ec15-contact-banner h2{font-size:30px;margin:0}.ec15-contact-banner p{margin-bottom:0}.ec15-contact-banner strong{font-size:30px;border-left:2px solid #fff;padding-left:40px}.ec15-contact-banner strong i{margin-right:12px}.ec15-contact-banner a{background:#fff;color:#111;padding:16px 26px;border-radius:7px;font-weight:700;text-transform:uppercase}.ec15-process{display:grid;grid-template-columns:repeat(4,1fr);gap:28px}.ec15-process article{text-align:center;position:relative}.ec15-process article>span{position:absolute;left:22%;top:0;width:38px;height:38px;border-radius:50%;background:var(--ec15-copper);color:#fff;display:grid;place-items:center}.ec15-process article>i{width:150px;height:150px;border:4px solid var(--ec15-copper);border-radius:50%;display:grid;place-items:center;margin:8px auto 34px;color:var(--ec15-copper);font-size:52px;box-shadow:var(--ec15-shadow)}.ec15-process h3{font-size:21px}.ec15-process p{color:var(--ec15-muted);line-height:1.55}.ec15-reasons{background:var(--ec15-paper)}.ec15-reasons-layout{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}.ec15-reasons article{display:flex;gap:18px;border-bottom:1px solid #dfd5cf;padding:24px 0}.ec15-reasons article>i{width:56px;height:56px;border-radius:50%;border:3px solid var(--ec15-copper);display:grid;place-items:center;color:var(--ec15-copper);font-size:25px;flex:0 0 auto}.ec15-reasons article h3{margin:0 0 8px}.ec15-reasons article p{margin:0;color:var(--ec15-muted);line-height:1.6}.ec15-reasons figure{margin:0;border:6px solid var(--ec15-copper);padding:28px 0 28px 28px}.ec15-reasons figure img{width:calc(100% + 34px);height:600px;object-fit:cover}.ec15-faq-layout{display:grid;grid-template-columns:.9fr 1.1fr;gap:80px}.ec15-faq-layout>div:first-child>a{display:inline-block;margin-top:28px;background:var(--ec15-copper);color:#fff;padding:16px 28px;border-radius:6px;text-transform:uppercase;font-weight:700}.ec15-accordion{display:grid;gap:18px}.ec15-accordion article{border-radius:12px;box-shadow:var(--ec15-shadow);overflow:hidden}.ec15-accordion button{width:100%;border:0;background:#fff;padding:20px 24px;display:flex;align-items:center;gap:18px;font:inherit;text-align:left}.ec15-accordion button i{width:46px;height:46px;border-radius:50%;background:var(--ec15-copper);color:#fff;display:grid;place-items:center;font-size:24px;font-style:normal}.ec15-accordion button b{flex:1;font-size:18px}.ec15-accordion article p{display:none;padding:0 28px 24px 88px;line-height:1.6;margin:0}.ec15-accordion article.is-open p{display:block}.ec15-accordion article.is-open button span{transform:rotate(180deg)}.ec15-testimonials{background:var(--ec15-paper)}.ec15-testimonial-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.ec15-testimonial-grid>article{background:#fff;padding:28px;border-radius:10px;border-bottom:4px solid var(--ec15-copper)}.ec15-stars{color:var(--ec15-copper);letter-spacing:8px}.ec15-testimonial-grid>article>p{line-height:1.7;min-height:120px}.ec15-testimonial-grid footer{border-top:1px solid #eee;padding-top:18px;display:flex;align-items:center;gap:14px}.ec15-testimonial-grid footer>span{width:54px;height:54px;border-radius:50%;border:4px solid var(--ec15-copper);display:grid;place-items:center;font-weight:700;font-size:22px}.ec15-testimonial-grid footer div{flex:1}.ec15-testimonial-grid footer b,.ec15-testimonial-grid footer small{display:block}.ec15-testimonial-grid footer small{color:var(--ec15-copper)}.ec15-testimonial-grid footer>i{font-size:34px;color:var(--ec15-copper)}.ec15-news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:34px}.ec15-news-grid article>a{display:block;height:280px;border-radius:10px;overflow:hidden}.ec15-news-grid img{width:100%;height:100%;object-fit:cover;transition:.4s}.ec15-news-grid article:hover img{transform:scale(1.04)}.ec15-news-grid small{display:block;margin:18px 0 8px}.ec15-news-grid small i{color:var(--ec15-copper);margin-right:8px}.ec15-news-grid h3{font-size:19px;line-height:1.5}.ec15-news-grid p{color:#666;line-height:1.6}.ec15-footer{background:#191919;color:#ddd;padding-top:70px}.ec15-footer-grid{display:grid;grid-template-columns:1.25fr .8fr .9fr 1.1fr;gap:60px}.ec15-footer .ec15-logo{margin-bottom:25px}.ec15-footer section>p{line-height:1.7}.ec15-footer h3{color:#fff;text-transform:uppercase}.ec15-footer section>a{display:block;margin:17px 0}.ec15-contact p{display:flex;gap:14px;align-items:center}.ec15-contact i{width:42px;height:42px;border-radius:12px;background:var(--ec15-copper);display:grid;place-items:center}.ec15-instagram{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.ec15-instagram img{aspect-ratio:1;object-fit:cover;border-radius:9px}.ec15-copyright{border-top:1px solid #333;margin-top:55px;padding:20px;text-align:center;color:#777;font-size:13px}
/* Scroll reveal: JS adds motion-ready only when motion is allowed. */
.ec15-motion-ready [data-ec15-reveal],.ec15-motion-ready [data-ec15-motion],.ec15-motion-ready [data-ec15-stagger]{opacity:0;will-change:transform,opacity,clip-path}.ec15-motion-ready [data-ec15-reveal]{transform:translateY(56px);transition:opacity .75s ease,transform .85s cubic-bezier(.2,.75,.2,1)}.ec15-motion-ready [data-ec15-motion="left"]{transform:translateX(-70px);transition:opacity .8s ease,transform .9s cubic-bezier(.2,.75,.2,1)}.ec15-motion-ready [data-ec15-motion="right"]{transform:translateX(70px);transition:opacity .8s ease,transform .9s cubic-bezier(.2,.75,.2,1)}.ec15-motion-ready [data-ec15-motion="scale"]{transform:scale(.92);transition:opacity .7s ease,transform .85s cubic-bezier(.2,.75,.2,1)}.ec15-motion-ready [data-ec15-stagger]{transform:translateY(38px);transition:opacity .6s ease,transform .7s cubic-bezier(.2,.75,.2,1);transition-delay:var(--ec15-delay,0ms)}.ec15-motion-ready [data-ec15-reveal].is-visible,.ec15-motion-ready [data-ec15-motion].is-visible,.ec15-motion-ready [data-ec15-stagger].is-visible{opacity:1;transform:none}.ec15-motion-ready [data-ec15-reveal].is-visible [data-ec15-motion],.ec15-motion-ready [data-ec15-reveal].is-visible [data-ec15-stagger]{opacity:1;transform:none}
.ec15-inner-hero{padding:170px 0 70px;background:linear-gradient(135deg,#2b2420,#8b624d);color:#fff}.ec15-inner-hero h1{font-size:46px}.ec15-content{padding:70px 0;min-height:420px}.ec15-listing{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.ec15-listing article{border:1px solid var(--ec15-line);border-radius:12px;overflow:hidden}.ec15-listing img{width:100%;height:260px;object-fit:cover}.ec15-listing article>div{padding:20px}.ec15-prose{font-size:16px;line-height:1.8}.ec15-form{display:grid;gap:14px;max-width:700px}.ec15-form input,.ec15-form textarea{padding:13px;border:1px solid var(--ec15-line);border-radius:7px;font:inherit}.ec15-button{display:inline-flex;background:var(--ec15-copper);color:#fff!important;border:0;border-radius:6px;padding:13px 22px;font-weight:700}.ec15-product-detail{display:grid;grid-template-columns:1fr 1fr;gap:45px}.ec15-product-detail img{width:100%;border-radius:12px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
@media(max-width:1180px){.ec15-header-inner{gap:20px}.ec15-logo{min-width:210px}.ec15-header nav{gap:14px}.ec15-product-grid{grid-template-columns:repeat(3,1fr)}.ec15-footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:820px){.ec15-container{width:calc(100% - 28px)}.ec15-header-inner{height:76px}.ec15-header nav{display:none;position:absolute;top:76px;left:0;right:0;background:#191715;padding:18px 28px;flex-direction:column;align-items:flex-start}.ec15-header nav.is-open{display:flex}.ec15-menu-toggle{display:block!important}.ec15-header-actions{margin-left:auto}.ec15-header-actions>a:not(.ec15-cart){display:none}.ec15-hero{min-height:650px}.ec15-hero-copy{padding-inline:28px}.ec15-hero-copy h1{font-size:38px}.ec15-section{padding:68px 0}.ec15-about-layout,.ec15-reasons-layout,.ec15-faq-layout{grid-template-columns:1fr;gap:45px}.ec15-room-grid{grid-template-columns:1fr 1fr;grid-template-rows:240px 240px 240px}.ec15-room-grid .item-1{grid-column:span 2;grid-row:auto}.ec15-product-grid{grid-template-columns:repeat(2,1fr)}.ec15-contact-banner article{grid-template-columns:1fr;padding:28px}.ec15-contact-banner strong{border-left:0;padding-left:0}.ec15-process{grid-template-columns:1fr 1fr}.ec15-testimonial-grid,.ec15-news-grid{grid-template-columns:1fr}.ec15-footer-grid{grid-template-columns:1fr}.ec15-listing{grid-template-columns:1fr 1fr}.ec15-product-detail{grid-template-columns:1fr}}
@media(max-width:520px){.ec15-logo span{font-size:32px}.ec15-logo b{font-size:21px}.ec15-header-actions{gap:14px}.ec15-hero-copy h1{font-size:31px}.ec15-hero-copy>span{letter-spacing:2px}.ec15-about h2,.ec15-reasons h2,.ec15-faq h2{font-size:34px}.ec15-stats{grid-template-columns:1fr}.ec15-room-grid{display:flex;overflow-x:auto}.ec15-room-grid a{min-width:84vw;height:330px}.ec15-product-grid{gap:10px}.ec15-product{padding:8px}.ec15-product-meta h3{font-size:13px}.ec15-product-meta p{display:block}.ec15-heading h2{font-size:34px}.ec15-contact-banner{height:620px}.ec15-contact-banner article{width:calc(100% - 28px)}.ec15-process{grid-template-columns:1fr}.ec15-reasons figure img{height:400px}.ec15-listing{grid-template-columns:1fr}}
</style>
